# Fresh Kaggle TPU v5e-8 notebook. Enable Internet. See No attachments needed; frozen seed3 paired25k endpoint, 5k screen report-only..
import base64, hashlib, io, json, pathlib, runpy, sys, unittest, zipfile
SEED=3
RESUME=False
payload=base64.b64decode('')
assert hashlib.sha256(payload).hexdigest()=='2faf38189b0024e80ba200be24fa9a7bdae2fc0525254089e62ba14185c48f1a'
ROOT=pathlib.Path('/kaggle/working/local_kv_frozen_endpoint_seed'+str(SEED)+'_'+'2faf38189b0024e80ba200be24fa9a7bdae2fc0525254089e62ba14185c48f1a'[:12])
ROOT.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    for name in archive.namelist():
        assert pathlib.PurePosixPath(name).name==name
        (ROOT/name).write_bytes(archive.read(name))
OUT=ROOT/'output'; OUT.mkdir(exist_ok=True)
if (OUT/'screen_result.json').exists():
    raise RuntimeError('Existing run preserved. Use a fresh session, not an accidental restart from scratch.')
saved_argv=sys.argv[:]; saved_path=sys.path[:]
module_names=('models','two_stage','local_context','local_kv','tpu_lm_train','enwik8_data','test_local_kv','run_screen','run_endpoint','endpoint_recovery','test_endpoint_recovery')
saved_modules={name:sys.modules.pop(name) for name in module_names if name in sys.modules}
try:
    sys.path.insert(0,str(ROOT))
    import jax
    jax.config.update('jax_default_matmul_precision','highest')
    if jax.default_backend()!='tpu' or jax.device_count()!=8:
        raise RuntimeError('Select TPU v5e-8 and restart the session. This experiment is not a GPU run.')
    print('LOCAL_KV_TPU_READY',jax.__version__,list(map(str,jax.devices())),flush=True)
    import test_local_kv, test_endpoint_recovery
    suite=unittest.TestSuite(unittest.defaultTestLoader.loadTestsFromModule(m) for m in (test_local_kv,test_endpoint_recovery))
    result=unittest.TextTestRunner(verbosity=2).run(suite)
    if not result.wasSuccessful(): raise RuntimeError('Correctness tests failed; no training launched.')
    jax.clear_caches()
    sys.argv=[str(ROOT/'run_seed3_frozen_endpoint.py'),'--outdir',str(OUT),'--seed',str(SEED)]
    if RESUME: sys.argv.append('--resume')
    print('RUN_LOCAL_KV_ENDPOINT',' '.join(sys.argv),flush=True)
    runpy.run_path(str(ROOT/'run_seed3_frozen_endpoint.py'),run_name='__main__')
finally:
    sys.argv=saved_argv; sys.path[:]=saved_path
    for name in module_names: sys.modules.pop(name,None)
    sys.modules.update(saved_modules)
    compact=ROOT.parent/(ROOT.name+'_compact.zip')
    with zipfile.ZipFile(compact,'w',zipfile.ZIP_DEFLATED) as archive:
        for path in ROOT.rglob('*'):
            if path.is_file() and '__pycache__' not in path.parts and path.suffix not in ('.pkl','.partial'):
                archive.write(path,path.relative_to(ROOT).as_posix())
    print('LOCAL_KV_COMPACT_ARCHIVE',str(compact),flush=True)
    print('LOCAL_KV_FULL_CHECKPOINT_DIRECTORY',str(OUT),flush=True)
    print('Compact archive EXCLUDES checkpoints. Save notebook outputs to preserve both .pkl files.',flush=True)
